import os,pathlib,sys
root=pathlib.Path.cwd().resolve()
for d in pathlib.Path("/proc").iterdir():
 if not d.name.isdigit():continue
 try:
  args=[a.decode("utf-8","replace") for a in (d/"cmdline").read_bytes().split(b"\0") if a]
  if "tumblrkit.appserve" not in args or "serve" not in args or (d/"cwd").resolve()!=root:continue
  entries=(d/"environ").read_bytes().split(b"\0")
  def lookup(key):
   pre=key.encode()+b"="
   return next((v[len(pre):] for v in entries if v.startswith(pre)),b"")
  blog=lookup("TUMBLR_OWNER_BLOG"); token=lookup("TUMBLR_OAUTH_ACCESS_TOKEN_FILE")
  if not blog and not token:sys.exit(40)
  if not blog:sys.exit(41)
  if not token:sys.exit(42)
  f=pathlib.Path(os.fsdecode(token)).expanduser()
  if not f.is_file() or f.is_symlink() or f.stat().st_mode&0o077:sys.exit(43)
  sys.exit(0)
 except (OSError,PermissionError,ValueError):continue
sys.exit(44)
